'use strict';
// R630 said "zero orphans: all 189 tools are mentioned". This round found that 41 of the 51 evidence-only tools are mentioned
// ONLY by index machinery — `SCRIPT-INDEX.md`, `TOPIC-INDEX.md`, `STATUS.md`, and R628–R630's own documents. The mention was
// generated by the record, not by a use of the tool.
//
// THE MEASUREMENT
//       evidence-only tools                                     51
//       mentioned ONLY in generated indexes / STATUS            41
//       mentioned in a round-specific evidence document         10
//
//   A `SCRIPT-INDEX.md` line reading "- `proof-r389-held-withdrawn.cjs` 被引用" is not a use of that tool. It is the index
//   reporting that the tool exists. Counting it as coverage is the same circularity as making a citation that proves itself.
//
// WHY R630 WAS WRONG, PRECISELY
//   R630 measured "mentioned as a whole token outside tools/" — a property any generated index satisfies by construction, because
//   building the index requires listing every tool. So the 189/189 result was true and uninformative: the index cannot fail to
//   mention a tool it enumerates.
//
//   The corrected question is whether a tool appears in a document that exists for a REASON other than enumerating tools. On that
//   question, 41 tools have no such mention, and 10 do.
//
// WHAT THE 41 ARE
//   Mostly `proof-*` and `probe-*` one-shots: `proof-consent-hidden`, `proof-packaged-cli-mcp`, `probe-regwrite`,
//   `probe-main-write`, `official-oauth-constants`. Each was written for one measurement, ran once, and left no round document
//   citing it — the round's `evidence/*.md` describes the FINDING without naming the script.
//
//   That is a real gap in the record's traceability, not a defect in the tools: a reader who wants to know how a finding was
//   obtained cannot follow a name back to a script, because the name is only in the inventory.
//
// WHAT IS NOT CLAIMED
//   Not that the 41 are broken or unused: they ran, and several produced findings that ARE recorded. What is missing is the link
//   from finding to instrument.
//   Not that `STATUS.md` should be excluded in general: a STATUS block that says "ran `tools/x.cjs` and it reported N" IS a use.
//   The 41 are the ones where no STATUS line does that — only the enumeration does.

/** The corrected coverage. */
const COVERAGE = {
  evidenceOnly: 51,
  mentionedOnlyByIndex: 41,
  mentionedInARoundDocument: 10,
  note: 'an index that enumerates tools cannot fail to mention them, so R630\'s 189/189 was true and uninformative',
};

/** What the 41 are, and what is actually missing. */
const GAP = {
  example: 'proof-consent-hidden, proof-packaged-cli-mcp, probe-regwrite, probe-main-write, official-oauth-constants',
  shape: 'written for one measurement, ran once, and no round document cites it — the evidence describes the finding without naming the script',
  whatIsMissing: 'the link from finding to instrument',
  notMissing: 'the tools did not fail; several produced findings that ARE recorded',
};

/** The circularity, stated so the next measurement does not repeat it. */
const CIRCULARITY = {
  rule: 'a generated index mentioning a tool is not evidence the tool was used',
  why: 'building the index requires listing every tool, so the mention holds by construction',
  correctedQuestion: 'does the tool appear in a document that exists for a reason other than enumerating tools',
};

module.exports = { COVERAGE, GAP, CIRCULARITY };
